export async function getJSON(path) {
  const response = await fetch(path, {
    headers: {
      Accept: "application/json",
    },
  });
  if (!response.ok) {
    throw new Error(`Request failed: ${response.status}`);
  }
  return response.json();
}

export async function getFastApiJSON(path) {
  // Quote endpoint lives on the standalone HTTP bridge (ws_http_bridge.py)
  // Default: http://127.0.0.1:8766/api/quote?symbol=...&exchange=...
  // You can override via .env: REACT_APP_FASTAPI_HTTP_BASE=http://127.0.0.1:8766
  const base = process.env.REACT_APP_FASTAPI_HTTP_BASE || "http://127.0.0.1:8766";
  const url = path.startsWith("http") ? path : `${base}${path}`;
  const response = await fetch(url, {
    headers: {
      Accept: "application/json",
    },
  });
  if (!response.ok) {
    throw new Error(`Request failed: ${response.status}`);
  }
  return response.json();
}
